撤回并查集（基于栈记录）
struct BCJ{ int pu,pv,old_mx,old_sz; };
stack <BCJ> s;
void merge(int u,int v){
    int ru=find(u),rv=find(v);
    if(ru==rv){
        s.push({-1,-1,-1,-1});
        return ;
    }
    if(sz[ru]<sz[rv]) swap(ru,rv);
    s.push({ru,rv,mx[ru],sz[ru]});
    pa[rv]=ru;
    mx[ru]=max(mx[ru],mx[rv]);
    sz[ru]+=sz[rv];
}
void ctrlz(){
    if(s.empty()) return ;
    BCJ p=s.top();
    s.pop();
    if(p.pu==-1) return ;
    pa[p.pv]=p.pv;
    mx[p.pu]=p.old_mx;
    sz[p.pu]=p.old_sz;
}

