ST表
int dp[N][20];
void ST(){
    for(int j=1;j<=log2(n);j++){
        for(int i=1;i<=n-(1<<j)+1;i++){
            dp[i][j]=max(dp[i][j-1],dp[i+(1<<(j-1))][j-1]);
        }
    }
}
int RMQ(int l,int r){
    int k=log2(r-l+1);
    return max(dp[l][k],dp[r-(1<<k)+1][k]);
}

